type SearchRequest struct {
	Keywords string            `json:"keywords,omitempty"`
	Page     int               `json:"page,omitempty"`
	Pagesize int               `json:"pagesize,omitempty"`
	Type     any               `json:"type,omitempty"`
	Cookie   map[string]string `json:"-"`
	Extra    map[string]any    `json:"-"`
}

type SearchResponse = Response

func (c *Client) Search(ctx context.Context, req SearchRequest) (*SearchResponse, error) {
	params := structToMap(req)
	delete(params, "Cookie")
	delete(params, "Extra")
	for k, v := range req.Extra {
		params[k] = v
	}

	kind := firstNonEmpty(fmt.Sprintf("%v", firstAny(params["type"], req.Type)), "song")
	valid := map[string]struct{}{
		"special": {},
		"lyric":   {},
		"song":    {},
		"album":   {},
		"author":  {},
		"mv":      {},
	}
	if _, ok := valid[kind]; !ok {
		kind = "song"
	}

	ver := "v1"
	if kind == "song" {
		ver = "v3"
	}

	resp, err := c.Call(ctx, RouteSearch, Request{
		Method: "GET",
		URL:    "/" + ver + "/search/" + kind,
		Params: map[string]any{
			"albumhide":    0,
			"iscorrection": 1,
			"keyword":      firstNonEmpty(fmt.Sprintf("%v", firstAny(params["keywords"], req.Keywords)), ""),
			"nocollect":    0,
			"page":         toInt(firstAny(params["page"], req.Page), 1),
			"pagesize":     toInt(firstAny(params["pagesize"], req.Pagesize), 30),
			"platform":     "AndroidFilter",
		},
		Cookie:      req.Cookie,
		EncryptType: "android",
		Headers:     map[string]string{"x-router": "complexsearch.kugou.com"},
	})
	if err != nil {
		return nil, err
	}
	out := SearchResponse(*resp)
	return &out, nil
}

